// Explicit forms: only tables with a person column and an inflected form header. No prose/example rows hidden.
function tableIsConjugation(t){let h=t[1].map(x=>String(x).toLowerCase());let person=/лицо|persona|pronombre/.test(h[0]||'');let paradigms=/presente|futuro|imperfecto|indefinido|condicional|subjuntivo|imperativo|hablar|comer|vivir|tener|hacer|poder|venir|decir|poner|ir|ser|ver|salir|saber|форма|forma/.test(h.slice(1).join(' ')+' '+t[0].toLowerCase());return person&&paradigms}
function cellTaskId(section,table,ri,ci){return `gram:${section}:${table}:${ri}:${ci}`}
function verifyTableCell(id,expected,field){let v=field.value;if(!v.trim()){field.setCustomValidity('Сначала введите форму');field.reportValidity();field.setCustomValidity('');return}let ok=normal(v)===normal(expected);let prior=state.answers[id]||{n:0},n=ok?Math.min(5,prior.n+1):0;state.answers[id]={n,correct:ok,due:Date.now()+(ok?[0,1,3,7,14,30][n]:0)*DAY_MS};let td=field.closest('td');let feedback=td.querySelector('.cell-feedback');feedback.textContent=ok?'✓ Верно':`✗ Правильно: ${expected}`;feedback.className='cell-feedback '+(ok?'correct':'incorrect');field.disabled=true;save()}
function createTrainingTable(t){let safeEsc=v=>esc(String(v));let canTrain=tableIsConjugation(t);return `<div class="tablewrap"><table><thead><tr>${t[1].map(v=>`<th>${safeEsc(v)}</th>`).join('')}</tr></thead><tbody>${t[2].map((r,ri)=>`<tr>${r.map((v,ci)=>{let e=safeEsc(v);if(!studyHide||!canTrain||ci===0||!String(v).trim())return `<td>${e}</td>`;let id=cellTaskId(section,table,ri,ci),safeID=JSON.stringify(id),safeAnswer=JSON.stringify(String(v));return `<td><details><summary>Вспомнить форму</summary><div class="form-task"><input aria-label="${safeEsc(t[1][ci])}: ${safeEsc(r[0])}" autocomplete="off" autocapitalize="off" spellcheck="false" onkeydown="if(event.key==='Enter')verifyTableCell(${safeID},${safeAnswer},this)"><button onclick="verifyTableCell(${safeID},${safeAnswer},this.previousElementSibling)">Проверить</button><button onclick="this.closest('td').querySelector('.cell-feedback').textContent=${safeAnswer}">Ответ</button><div class="cell-feedback" aria-live="polite"></div></div></details></td>`}).join('')}</tr>`).join('')}</tbody></table></div>${canTrain?'<p class="muted">Тренируются только формы спряжений: введите ответ в раскрытой ячейке. Заголовки и пояснения не скрываются.</p>':'<p class="muted">В этой таблице нет размеченных форм спряжения; её содержимое доступно для изучения без автоматического скрытия.</p>'}`}
const oldTables=tablesHTML;
tablesHTML=function(){let out=oldTables();let sec=DB.atlas[section],t=sec[1][Math.min(table,sec[1].length-1)];let start=out.indexOf('<div class="tablewrap"><table>');if(start<0)return out;let end=out.indexOf('</section>',start);if(end<0)return out;return out.slice(0,start)+createTrainingTable(t)+out.slice(end)};
