const SETTINGS_THEME_KEY='mi-espanol-theme-v1';let themeFallback='system',settingScreen=false;
function getThemePreference(){try{return localStorage.getItem(SETTINGS_THEME_KEY)||themeFallback}catch(e){return themeFallback}}
function applyTheme(){let pref=getThemePreference(),dark=pref==='dark'||(pref==='system'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.body.dataset.theme=dark?'dark':'light'}
function setTheme(pref){if(!['light','dark','system'].includes(pref))return;themeFallback=pref;try{localStorage.setItem(SETTINGS_THEME_KEY,pref)}catch(e){alert('Тема применена, но после закрытия страницы может сброситься: сохранение недоступно.')}applyTheme();render()}
function openSettings(){settingScreen=true;render();window.scrollTo(0,0)}
function closeSettings(){settingScreen=false;render()}
function contentManifest(){let imageCounts={};for(let im of DB.images){let k=(im.group||im.type||'прочее');imageCounts[k]=(imageCounts[k]||0)+1}return {sections:DB.atlas.length,tables:DB.atlas.reduce((n,x)=>n+x[1].length,0),words:DB.vocab.length,schemes:DB.schemes.length,exercises:DB.quiz.length,weeks:DB.weeks.length,images:DB.images.length,groups:imageCounts}}
function settingsHTML(){let m=contentManifest(),t=getThemePreference(),rows=[['Разделы грамматики',m.sections],['Цифровые таблицы',m.tables],['Словарные записи',m.words],['Речевые схемы',m.schemes],['Упражнения',m.exercises],['Недели маршрута',m.weeks],['Оригинальные изображения',m.images]];
return `<h2>Настройки и паспорт сборки</h2><section class="panel"><button onclick="closeSettings()">← Назад к прогрессу</button><h3>Оформление</h3><button onclick="setTheme('light')">☀ Восстановить светлую тему</button><p class="muted">Тёмная тема удобнее вечером. Режим «Системная» следует настройкам iPhone.</p><label for="theme-choice">Тема приложения</label><select id="theme-choice" class="field" onchange="setTheme(this.value)"><option value="system" ${t==='system'?'selected':''}>Как на устройстве</option><option value="light" ${t==='light'?'selected':''}>Светлая</option><option value="dark" ${t==='dark'?'selected':''}>Тёмная</option></select></section><section class="panel"><h3>Аудиопроизношение</h3><p class="muted">Испанский голос устройства · es-ES. Звук запускается нажатием кнопки.</p><label for="speech-speed">Скорость</label><select class="field" id="speech-speed" onchange="audioRate=Number(this.value)"><option value="0.7">Медленно</option><option value="0.85" selected>Нормально</option><option value="1">Быстро</option></select><div class="row"><button class="audio-button primary" onclick="testSpeech()">🔊 Проверить произношение</button><button onclick="speechSynthesis.cancel();audioInfo('Остановлено')">■ Стоп</button></div><div id="speech-status" class="sound-status" aria-live="polite"></div></section>
<section class="panel"><h3>Паспорт сборки</h3><p class="settings-caption">Версия: ${esc(RELEASE_INFO.version)}</p><p class="settings-caption">Основа: ${esc(RELEASE_INFO.base)}</p><table class="settings-table"><thead><tr><th>Материал</th><th>Встроено</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${x[1]}</td></tr>`).join('')}</tbody></table><p class="settings-caption">Эти числа вычисляются из загруженной учебной базы. Они показывают наличие записей, но не подтверждают их полноту или лингвистическую точность.</p><button onclick="exportManifest()">Сохранить паспорт (JSON)</button></section>
<section class="panel"><h3>Что изменилось</h3><ul>${RELEASE_INFO.changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="panel"><h3>Незакрытые требования</h3><ul>${RELEASE_INFO.known.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`}
function exportManifest(){let payload={release:RELEASE_INFO,counts:contentManifest(),exportedAt:new Date().toISOString()};let blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Mi_Espanol_build_manifest.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
applyTheme();if(window.matchMedia){let mq=window.matchMedia('(prefers-color-scheme: dark)');if(mq.addEventListener)mq.addEventListener('change',()=>{if(getThemePreference()==='system')applyTheme()})}
render();

/* Mi Español — stage 11 reconstruction patch for the ARCHIVED baseline only.
   This patch does not restore missing Stage10 content or claim user acceptance. */
const MI11_SETTINGS_KEY='mi-espanol-recovery11-settings-v1';
const MI11_SETTINGS_DEFAULT={fontScale:'normal',reducedMotion:false,audioRate:0.85};
function mi11SafeParse(s){try{return JSON.parse(s)}catch(e){return null}}
function mi11IsObject(v){return v!==null&&typeof v==='object'&&!Array.isArray(v)}
function mi11Clean(v,depth=0,count={n:0}){
 if(++count.n>150000||depth>30)throw Error('Слишком сложная структура файла');
 if(v===null||typeof v==='string'||typeof v==='boolean')return v;
 if(typeof v==='number'&&Number.isFinite(v))return v;
 if(Array.isArray(v))return v.map(x=>mi11Clean(x,depth+1,count));
 if(!mi11IsObject(v))throw Error('Недопустимые данные в резервной копии');
 let o=Object.create(null);
 for(let k of Object.keys(v)){
  if(['__proto__','prototype','constructor'].includes(k))throw Error('Недопустимое имя поля');
  o[k]=mi11Clean(v[k],depth+1,count);
 }
 return o;
}
